import { analyzeFrontendCode } from './analyzeFrontendCode.js';
import { recommendAnimations } from './recommendAnimations.js';
import { generateIntegrationCode } from './generateIntegrationCode.js';
import { getComponentByName } from '../utils/dataLoader.js';

/**
 * Comprehensive tool to analyze code and provide complete animation optimization recommendations
 */
export async function optimizeFrontendWithAnimations(args) {
  const { 
    code, 
    userRequest, 
    framework = 'react', 
    techStack = 'js-css', 
    budget = 'moderate' 
  } = args;

  try {
    // Step 1: Analyze the frontend code
    console.error('Analyzing frontend code...');
    const analysisResult = await analyzeFrontendCode({ code, framework, codeType: 'component' });
    const analysis = parseAnalysisResult(analysisResult);

    // Step 2: Get animation recommendations based on user request
    console.error('Generating recommendations...');
    const recommendationsResult = await recommendAnimations({ 
      requirement: userRequest, 
      codeContext: code, 
      priority: 'user-experience', 
      techStack 
    });
    const recommendations = parseRecommendationsResult(recommendationsResult);

    // Step 3: Create optimization plan
    console.error('Creating optimization plan...');
    const optimizationPlan = createOptimizationPlan(
      analysis, 
      recommendations, 
      userRequest, 
      budget, 
      techStack
    );

    // Step 4: Generate implementation code for top recommendations
    console.error('Generating implementation code...');
    const implementations = await generateImplementations(
      code, 
      optimizationPlan.selectedComponents, 
      techStack
    );

    // Step 5: Create comprehensive response
    const responseText = formatOptimizationResponse(
      userRequest,
      analysis,
      recommendations,
      optimizationPlan,
      implementations,
      techStack,
      budget
    );

    return {
      content: [
        {
          type: 'text',
          text: responseText
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error optimizing frontend: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Parse analysis result from analyzeFrontendCode
 */
function parseAnalysisResult(analysisResult) {
  // Extract key information from the analysis text
  const content = analysisResult.content[0].text;
  
  return {
    framework: extractValue(content, 'Framework:'),
    techStack: extractValue(content, 'Tech Stack:'),
    complexity: extractValue(content, 'Complexity:'),
    layout: extractValue(content, 'Layout Type:'),
    elements: extractElements(content),
    opportunities: extractOpportunities(content)
  };
}

/**
 * Parse recommendations result from recommendAnimations
 */
function parseRecommendationsResult(recommendationsResult) {
  const content = recommendationsResult.content[0].text;
  
  return {
    intent: extractValue(content, 'Detected Intent:'),
    components: extractRecommendedComponents(content)
  };
}

/**
 * Extract value from analysis text
 */
function extractValue(text, label) {
  const regex = new RegExp(`\\*\\*${label}\\*\\*\\s*([^\\n]+)`);
  const match = text.match(regex);
  return match ? match[1].trim() : 'unknown';
}

/**
 * Extract elements from analysis
 */
function extractElements(text) {
  const elements = [];
  const elementRegex = /- \*\*(\w+)\*\*: (\d+) instances \(([^)]+) animation potential\)/g;
  let match;
  
  while ((match = elementRegex.exec(text)) !== null) {
    elements.push({
      type: match[1],
      count: parseInt(match[2]),
      potential: match[3]
    });
  }
  
  return elements;
}

/**
 * Extract opportunities from analysis
 */
function extractOpportunities(text) {
  const opportunities = [];
  const oppRegex = /### \d+\. ([^\\n]+) Enhancement[\\s\\S]*?\*\*Priority:\*\* ([^\\n]+)[\\s\\S]*?\*\*Recommended Components:\*\* ([^\\n]+)/g;
  let match;
  
  while ((match = oppRegex.exec(text)) !== null) {
    opportunities.push({
      target: match[1],
      priority: match[2].trim(),
      components: match[3].split(', ').map(c => c.trim())
    });
  }
  
  return opportunities;
}

/**
 * Extract recommended components
 */
function extractRecommendedComponents(text) {
  const components = [];
  const compRegex = /### \d+\. ([^\\n]+)[\\s\\S]*?\*\*Category:\*\* ([^\\n]+)[\\s\\S]*?\*\*Description:\*\* ([^\\n]+)[\\s\\S]*?\*\*Usage complexity:\*\* ([^\\n]+)[\\s\\S]*?\*\*Performance impact:\*\* ([^\\n]+)/g;
  let match;
  
  while ((match = compRegex.exec(text)) !== null) {
    components.push({
      name: match[1].trim(),
      category: match[2].trim(),
      description: match[3].trim(),
      complexity: match[4].trim(),
      performance: match[5].trim()
    });
  }
  
  return components;
}

/**
 * Create optimization plan based on analysis and recommendations
 */
function createOptimizationPlan(analysis, recommendations, userRequest, budget, techStack) {
  const plan = {
    priority: determinePriority(userRequest),
    budget,
    phases: [],
    selectedComponents: [],
    estimatedEffort: 'medium',
    expectedImpact: 'high'
  };

  // Filter components based on budget
  const filteredComponents = filterComponentsByBudget(recommendations.components, budget);
  
  // Select top components based on priority and budget
  plan.selectedComponents = selectOptimalComponents(
    filteredComponents, 
    analysis.opportunities, 
    plan.priority, 
    budget
  );

  // Create implementation phases
  plan.phases = createImplementationPhases(plan.selectedComponents, budget);
  
  // Estimate effort and impact
  plan.estimatedEffort = estimateEffort(plan.selectedComponents, analysis.complexity);
  plan.expectedImpact = estimateImpact(plan.selectedComponents, userRequest);

  return plan;
}

/**
 * Determine priority from user request
 */
function determinePriority(userRequest) {
  const req = userRequest.toLowerCase();
  
  if (req.includes('loading') || req.includes('加载')) return 'loading';
  if (req.includes('interactive') || req.includes('交互')) return 'interaction';
  if (req.includes('beautiful') || req.includes('好看')) return 'visual';
  if (req.includes('engaging') || req.includes('吸引')) return 'engagement';
  
  return 'general';
}

/**
 * Filter components by budget
 */
function filterComponentsByBudget(components, budget) {
  const budgetFilters = {
    minimal: (comp) => comp.complexity === 'low' && comp.performance !== 'high',
    moderate: (comp) => comp.complexity !== 'high',
    extensive: () => true
  };
  
  return components.filter(budgetFilters[budget] || budgetFilters.moderate);
}

/**
 * Select optimal components
 */
function selectOptimalComponents(components, opportunities, priority, budget) {
  const maxComponents = {
    minimal: 2,
    moderate: 4,
    extensive: 6
  };

  // Score components based on priority and opportunities
  const scoredComponents = components.map(comp => ({
    ...comp,
    score: calculateComponentScore(comp, opportunities, priority)
  }));

  // Sort by score and take top N
  return scoredComponents
    .sort((a, b) => b.score - a.score)
    .slice(0, maxComponents[budget] || 4);
}

/**
 * Calculate component score
 */
function calculateComponentScore(component, opportunities, priority) {
  let score = 5; // Base score

  // Priority bonus
  const priorityBonus = {
    loading: component.category === 'backgrounds' ? 3 : 0,
    interaction: component.category === 'components' ? 3 : 0,
    visual: component.category === 'backgrounds' ? 2 : 1,
    engagement: 2
  };
  
  score += priorityBonus[priority] || 0;

  // Complexity penalty
  const complexityPenalty = {
    low: 0,
    medium: -1,
    high: -2
  };
  
  score += complexityPenalty[component.complexity] || 0;

  // Performance penalty
  const performancePenalty = {
    low: 0,
    medium: -1,
    high: -2
  };
  
  score += performancePenalty[component.performance] || 0;

  return score;
}

/**
 * Create implementation phases
 */
function createImplementationPhases(components, budget) {
  const phases = [];
  
  if (budget === 'minimal') {
    phases.push({
      name: 'Essential Animations',
      components: components.slice(0, 2),
      description: 'Core animations for immediate impact'
    });
  } else if (budget === 'moderate') {
    phases.push({
      name: 'Phase 1: Core Animations',
      components: components.slice(0, 2),
      description: 'Essential animations for immediate impact'
    });
    phases.push({
      name: 'Phase 2: Enhanced Interactions',
      components: components.slice(2, 4),
      description: 'Additional animations for better UX'
    });
  } else {
    phases.push({
      name: 'Phase 1: Foundation',
      components: components.slice(0, 2),
      description: 'Core animations and loading states'
    });
    phases.push({
      name: 'Phase 2: Interactions',
      components: components.slice(2, 4),
      description: 'Interactive elements and hover effects'
    });
    phases.push({
      name: 'Phase 3: Polish',
      components: components.slice(4, 6),
      description: 'Advanced animations and visual polish'
    });
  }
  
  return phases;
}

/**
 * Estimate implementation effort
 */
function estimateEffort(components, complexity) {
  const baseEffort = components.length * 2; // 2 hours per component
  const complexityMultiplier = {
    simple: 0.8,
    medium: 1.0,
    complex: 1.5
  };
  
  const totalHours = baseEffort * (complexityMultiplier[complexity] || 1.0);
  
  if (totalHours < 4) return 'low';
  if (totalHours < 8) return 'medium';
  return 'high';
}

/**
 * Estimate expected impact
 */
function estimateImpact(components, userRequest) {
  const highImpactKeywords = ['beautiful', 'stunning', 'engaging', '好看', '炫酷'];
  const hasHighImpactRequest = highImpactKeywords.some(keyword => 
    userRequest.toLowerCase().includes(keyword)
  );
  
  if (hasHighImpactRequest && components.length >= 3) return 'very-high';
  if (components.length >= 2) return 'high';
  return 'medium';
}

/**
 * Generate implementations for selected components
 */
async function generateImplementations(originalCode, selectedComponents, techStack) {
  const implementations = [];
  
  for (const component of selectedComponents.slice(0, 2)) { // Limit to top 2 for response size
    try {
      const integrationResult = await generateIntegrationCode({
        originalCode,
        componentName: component.name,
        techStack
      });
      
      implementations.push({
        component: component.name,
        integration: integrationResult.content[0].text
      });
    } catch (error) {
      console.error(`Failed to generate integration for ${component.name}:`, error);
    }
  }
  
  return implementations;
}

/**
 * Format comprehensive optimization response
 */
function formatOptimizationResponse(userRequest, analysis, recommendations, plan, implementations, techStack, budget) {
  let output = `# Frontend Animation Optimization Plan\n\n`;
  
  // Executive Summary
  output += `## Executive Summary\n\n`;
  output += `**Your Request:** "${userRequest}"\n`;
  output += `**Detected Priority:** ${plan.priority}\n`;
  output += `**Budget Level:** ${budget}\n`;
  output += `**Tech Stack:** ${techStack}\n`;
  output += `**Estimated Effort:** ${plan.estimatedEffort}\n`;
  output += `**Expected Impact:** ${plan.expectedImpact}\n\n`;

  // Code Analysis Summary
  output += `## Code Analysis Summary\n\n`;
  output += `- **Framework:** ${analysis.framework}\n`;
  output += `- **Complexity:** ${analysis.complexity}\n`;
  output += `- **Layout:** ${analysis.layout}\n`;
  output += `- **Key Elements:** ${analysis.elements.map(e => `${e.type} (${e.count})`).join(', ')}\n\n`;

  // Recommended Components
  output += `## Selected Components\n\n`;
  plan.selectedComponents.forEach((comp, index) => {
    output += `### ${index + 1}. ${comp.name}\n`;
    output += `- **Category:** ${comp.category}\n`;
    output += `- **Complexity:** ${comp.complexity}\n`;
    output += `- **Performance Impact:** ${comp.performance}\n`;
    output += `- **Description:** ${comp.description}\n\n`;
  });

  // Implementation Plan
  output += `## Implementation Plan\n\n`;
  plan.phases.forEach((phase, index) => {
    output += `### ${phase.name}\n`;
    output += `**Components:** ${phase.components.map(c => c.name).join(', ')}\n`;
    output += `**Description:** ${phase.description}\n\n`;
  });

  // Implementation Examples
  if (implementations.length > 0) {
    output += `## Implementation Examples\n\n`;
    implementations.forEach((impl, index) => {
      output += `### ${impl.component} Integration\n\n`;
      output += `${impl.integration}\n\n`;
    });
  }

  // Quick Start Guide
  output += `## Quick Start Guide\n\n`;
  output += `1. **Start with Phase 1** components for immediate impact\n`;
  output += `2. **Install dependencies** for each component as shown above\n`;
  output += `3. **Test each component** individually before combining\n`;
  output += `4. **Monitor performance** especially on mobile devices\n`;
  output += `5. **Iterate and refine** based on user feedback\n\n`;

  // Performance Considerations
  output += `## Performance Considerations\n\n`;
  const highPerfComponents = plan.selectedComponents.filter(c => c.performance === 'high');
  if (highPerfComponents.length > 0) {
    output += `⚠️ **High Performance Impact Components:** ${highPerfComponents.map(c => c.name).join(', ')}\n`;
    output += `- Test on lower-end devices\n`;
    output += `- Consider lazy loading\n`;
    output += `- Monitor frame rates\n\n`;
  } else {
    output += `✅ **Good Performance Profile** - Selected components have minimal performance impact\n\n`;
  }

  // Next Steps
  output += `## Next Steps\n\n`;
  output += `1. **Get detailed component code:** Use \`get-react-bits-component\` for each selected component\n`;
  output += `2. **See live demos:** Use \`get-react-bits-demo\` for usage examples\n`;
  output += `3. **Get installation help:** Use \`get-react-bits-install-guide\` for setup instructions\n`;
  output += `4. **Need more components?** Use \`search-react-bits-components\` to explore alternatives\n\n`;

  // Success Metrics
  output += `## Success Metrics\n\n`;
  output += `Track these metrics to measure the impact of your animations:\n`;
  output += `- User engagement time\n`;
  output += `- Click-through rates on animated elements\n`;
  output += `- User feedback on interface feel\n`;
  output += `- Page load times and performance scores\n`;

  return output;
}
